def objects(grid, frontier_color):
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; objs=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] not in (0,frontier_color) and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx] not in (0,frontier_color):
                            seen[ny][nx]=True; stack.append((ny,nx))
                objs.append(cells)
    return objs

def fall(grid):
    h,w=len(grid),len(grid[0])
    rf=next(i for i,row in enumerate(grid) if len(set(row))==1)
    fc=grid[rf][0]
    dirn=-1 if rf==0 else 1
    objs=objects(grid,fc)
    out=[row[:] for row in grid]
    for i,row in enumerate(out):
        for j in range(w): out[i][j]=0
    out[rf]=[fc]*w
    # closest to frontier first
    objs.sort(key=lambda c: min(c,key=lambda p:abs(p[0]-rf)) if False else (min(p[0] for p in c) if dirn==-1 else -max(p[0] for p in c)))
    occupied=set()
    for rf2 in range(h):
        if grid[rf2][0]==fc and len(set(grid[rf2]))==1: occupied.add((rf2,0))  # placeholder
    occupied={(rf,j) for j in range(w)}
    for cells in objs:
        cells=sorted(cells)
        # move step by step toward frontier until blocked
        while True:
            new=[(y+dirn,x) for y,x in cells]
            if any((y,x) in occupied or y<0 or y>=h for y,x in new):
                break
            cells=new
        for y,x in cells:
            out[y][x]=grid[[ (yy,xx) for yy,xx in []] and 0 or 0] if False else None
        # need original colors: recover from grid via original offsets
        occupied.update(cells)
    # redo with colors properly
    return objs

