def fall2(grid):
    h,w=len(grid),len(grid[0])
    rf=next(i for i,row in enumerate(grid) if len(set(row))==1)
    fc=grid[rf][0]
    dirn=-1 if rf==0 else 1
    objs=[]
    for cells in objects(grid,fc):
        col=grid[cells[0][0]][cells[0][1]]
        objs.append((cells,col))
    objs.sort(key=lambda t: min(p[0] for p in t[0]) if dirn==-1 else -max(p[0] for p in t[0]))
    out=[[0]*w for _ in range(h)]
    out[rf]=[fc]*w
    occupied={(rf,j) for j in range(w)}
    for cells,col in objs:
        cells=sorted(cells)
        while True:
            new=[(y+dirn,x) for y,x in cells]
            if any((y,x) in occupied or not(0<=y<h) for y,x in new): break
            cells=new
        for y,x in cells: out[y][x]=col; occupied.add((y,x))
    return out

